    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    # The side rails define two bands. Markers on one rail band project
    # horizontal rays toward their own edge, and also select matching-offset
    # rows in the opposite band for full horizontal stripes.
    left_rows = [r for r in range(h) if grid[r][0] != bg]
    right_rows = [r for r in range(h) if grid[r][-1] != bg]

    def markers(rows):
        result = []
        for r in rows:
            for c in range(1, w - 1):
                if grid[r][c] != bg:
                    result.append((r, c, grid[r][c]))
        return result

    left_marks = markers(left_rows)
    right_marks = markers(right_rows)

