        for r in left_rows:
            # Marker on left rail: extend toward left edge, and mirror its
            # offset row into the right-edge band as a full stripe.
            marks = [c for c in range(1, w - 1) if grid[r][c] != bg]
            for c in marks:
                color = grid[r][c]
                out[r][c] = 4
                for x in range(1, c):
                    if grid[r][x] == bg:
                        out[r][x] = color
                target = right_start + (r - left_start)
                if target < h:
                    for x in range(1, w - 1):
                        if grid[target][x] == bg:
                            out[target][x] = color
        for r in right_rows:
            # Symmetric rule for a marker in the right rail band.
            marks = [c for c in range(1, w - 1) if grid[r][c] != bg]
            for c in marks:
                color = grid[r][c]
                out[r][c] = 4
                for x in range(c + 1, w - 1):
                    if grid[r][x] == bg:
                        out[r][x] = color
                target = left_start + (r - right_start)
                if target < h:
                    for x in range(1, w - 1):
